/**
 * body.ts — rigid body: an axis-aligned box (dynamic or static).
 * Rotation-free for simplicity; all state is position + velocity.
 */

export interface Vec2 {
  x: number;
  y: number;
}

export interface BodyOptions {
  /** Center of the box. */
  position?: Vec2;
  velocity?: Vec2;
  /** Half extents along x and y. */
  halfExtent?: Vec2;
  /** Mass of the box (ignored when static). */
  mass?: number;
  isStatic?: boolean;
}

export class Body {
  readonly position: Vec2;
  readonly velocity: Vec2;
  readonly halfExtent: Vec2;
  readonly inverseMass: number;
  readonly isStatic: boolean;

  constructor(options: BodyOptions = {}) {
    this.position = options.position ?? { x: 0, y: 0 };
    this.velocity = options.velocity ?? { x: 0, y: 0 };
    this.halfExtent = options.halfExtent ?? { x: 0.5, y: 0.5 };
    this.isStatic = options.isStatic ?? false;

    if (this.isStatic) {
      this.inverseMass = 0;
    } else {
      const mass = options.mass ?? 1;
      if (!(mass > 0)) throw new Error("Dynamic body mass must be > 0");
      this.inverseMass = 1 / mass;
    }
  }

  get min(): Vec2 {
    return {
      x: this.position.x - this.halfExtent.x,
      y: this.position.y - this.halfExtent.y,
    };
  }

  get max(): Vec2 {
    return {
      x: this.position.x + this.halfExtent.x,
      y: this.position.y + this.halfExtent.y,
    };
  }

  get speed(): number {
    return Math.hypot(this.velocity.x, this.velocity.y);
  }

  applyImpulse(ix: number, iy: number): void {
    this.velocity.x += ix * this.inverseMass;
    this.velocity.y += iy * this.inverseMass;
  }
}

