import { describe, expect, it } from "vitest";

import { Body } from "../src/body";
import { World } from "../src/world";

const DT = 1 / 60;

/** Floor: a wide static slab whose top surface sits at y = 0. */
function makeFloor(): Body {
  return new Body({
    position: { x: 0, y: -5 },
    halfExtent: { x: 100, y: 5 },
    isStatic: true,
  });
}

/**
 * Step until every dynamic body's speed is below `threshold`, measuring
 * after each step. Returns the number of ticks taken (600 cap).
 */
function ticksToRest(world: World, threshold = 0.01): number {
  let ticks = 0;
  do {
    world.step(DT);
    ticks++;
  } while (world.maxSpeed() >= threshold && ticks < 600);
  return ticks;
}

function dropBox(heightOfBottomAboveFloor: number) {
  const world = new World();
  const floor = world.addBody(makeFloor());
  const box = world.addBody(
    new Body({
      // bottom of box starts at `heightOfBottomAboveFloor`
      position: { x: 0, y: heightOfBottomAboveFloor + 0.5 },
      halfExtent: { x: 0.5, y: 0.5 },
      mass: 1,
    }),
  );
  return { world, floor, box };
}

describe("single falling box", () => {
  it("comes to rest on the floor within 600 ticks", () => {
    const { world, box } = dropBox(5);

    const ticks = ticksToRest(world);

    expect(ticks).toBeLessThan(600);
    expect(box.speed).toBeLessThan(0.01);
  });

  it("has final penetration under 0.02 once settled", () => {
    const { world, floor, box } = dropBox(5);
    world.run(600, DT);

    const penetration = floor.max.y - box.min.y;
    expect(penetration).toBeGreaterThanOrEqual(0); // actually touching
    expect(penetration).toBeLessThan(0.02);
  });
});

describe("stack of three boxes", () => {
  function makeStack() {
    const world = new World();
    const bodies = [world.addBody(makeFloor())];
    for (let i = 0; i < 3; i++) {
      bodies.push(
        world.addBody(
          new Body({
            position: { x: 0, y: i + 2.5 }, // stacked above the floor
            halfExtent: { x: 0.5, y: 0.5 },
            mass: 1,
          }),
        ),
      );
    }
    return { world, bodies };
  }

  it("settles with each box resting within 0.05 of the one below", () => {
    const { world, bodies } = makeStack();

    const ticks = ticksToRest(world);
    expect(ticks).toBeLessThan(600);

    // bodies[0] is the floor; check each dynamic box against the one below.
    for (let i = 1; i < bodies.length; i++) {
      const gap = bodies[i].min.y - bodies[i - 1].max.y;
      expect(Math.abs(gap)).toBeLessThanOrEqual(0.05);
    }
  });

  it("is deterministic: identical ticks-to-rest across two runs", () => {
    const runs: { ticks: number[]; positions: number[] }[] = [];

    for (let run = 0; run < 2; run++) {
      const { world, bodies } = makeStack();
      const ticks: number[] = [];
      for (let i = 0; i < 3; i++) {
        let t = 0;
        do {
          world.step(DT);
          t++;
        } while (bodies[i + 1].speed >= 0.01 && t < 600);
        ticks.push(t);
      }
      runs.push({
        ticks,
        positions: bodies.slice(1).map((b) => b.position.y),
      });
    }

    expect(runs[0].ticks).toEqual(runs[1].ticks);
    expect(runs[0].positions).toEqual(runs[1].positions);
  });
});

