arguments.content:
/**
 * solver.ts — collision detection (AABB vs AABB) and a warm-started
 * sequential-impulse velocity solver plus Baumgarte-style positional
 * correction. Impulses are accumulated (clamped at >= 0 for normals,
 * Coulomb cone for friction) and cached across steps so resting stacks
 * start each step already converged.
 */

import type { Body, Vec2 } from "./body";

export interface Contact {
  a: Body;
  b: Body;
  /** Unit contact normal pointing from `a` toward `b`. */
  normal: Vec2;
  /** Overlap depth along the normal (>= 0). */
  penetration: number;
  /** Accumulated normal impulse (warm-started from the previous step). */
  normalImpulse: number;
}

export function contactKey(c: Contact): string {
  return `${c.a.id}:${c.b.id}`;
}

/**
 * Narrow-phase AABB overlap. Returns the contact with the axis of minimum
 * penetration as the normal, or null when the bodies do not intersect.
 */
export function collide(a: Body, b: Body): Contact | null {
  const dx = b.position.x - a.position.x;
