/**
 * solver.ts — collision detection (AABB vs AABB) and a warm-started
 * sequential-impulse velocity solver plus Baumgarte-style positional
 * correction. Normal impulses are accumulated (clamped at >= 0, Coulomb
 * cone for friction) and cached across steps so resting stacks start each
 * step already converged.
 */

import type { Body, Vec2 } from "./body";

export interface Contact {
  a: Body;
  b: Body;
  /** Unit contact normal pointing from `a` toward `b`. */
  normal: Vec2;
  /** Overlap depth along the normal (>= 0). */
  penetration: number;
  /** Accumulated normal impulse (warm-started from the previous step). */
  normalImpulse: number;
}

export function contactKey(c: Contact): string {
  return `${c.a.id}:${c.b.id}`;
}

/**
 * Narrow-phase AABB overlap. Returns the contact with the axis of minimum
 * penetration as the normal, or null when the bodies do not intersect.
 */
export function collide(a: Body, b: Body): Contact | null {
  const dx = b.position.x - a.position.x;
  const dy = b.position.y - a.position.y;

  const overlapX = a.halfExtent.x + b.halfExtent.x - Math.abs(dx);
  if (overlapX <= 0) return null;

  const overlapY = a.halfExtent.y + b.halfExtent.y - Math.abs(dy);
  if (overlapY <= 0) return null;

  // Axis of least penetration becomes the collision normal.
  if (overlapX < overlapY) {
    const nx = dx < 0 ? -1 : 1;
    return { a, b, normal: { x: nx, y: 0 }, penetration: overlapX, normalImpulse: 0 };
  }
  const ny = dy < 0 ? -1 : 1;
  return { a, b, normal: { x: 0, y: ny }, penetration: overlapY, normalImpulse: 0 };
}

/** Broad phase: O(n^2) pair test, deterministic order. */
export function findContacts(
  bodies: readonly Body[],
  impulseCache: ReadonlyMap<string, number>,
): Contact[] {
  const contacts: Contact[] = [];
  for (let i = 0; i < bodies.length; i++) {
    for (let j = i + 1; j < bodies.length; j++) {
      const c = collide(bodies[i], bodies[j]);
      if (c === null) continue;
      // Warm start: seed with last step's accumulated impulse.
      c.normalImpulse = impulseCache.get(contactKey(c)) ?? 0;
      contacts.push(c);
    }
  }
  return contacts;
}

function applyPair(a: Body, b: Body, nx: number, ny: number, j: number): void {
  a.applyImpulse(-j * nx, -j * ny);
  b.applyImpulse(j * nx, j * ny);
}

/**
 * Resolve contacts with sequential impulses over `iterations` sweeps.
 *
 * Warm starting: each contact's accumulated `normalImpulse` is pre-applied
 * before the first sweep; during sweeps only the incremental impulse
 * needed to bring the relative normal velocity to zero is applied, and the
 * running total is clamped to be non-negative (no adhesion).
 *
 * On return, `impulseCache` holds this step's accumulated impulses keyed
 * by pair id (stale entries are evicted), for use as the next warm start.
 */
export function resolveVelocities(
  contacts: readonly Contact[],
  iterations: number,
  impulseCache: Map<string, number>,
  friction = 0.4,
): void {
  const invMassSumCache = contacts.map((c) => c.a.inverseMass + c.b.inverseMass);

  // Warm start: apply cached impulses before iterating.
  for (const c of contacts) {
    if (c.normalImpulse !== 0 && invMassSumCache[contacts.indexOf(c)] > 0) {
      applyPair(c.a, c.b, c.normal.x, c.normal.y, c.normalImpulse);
    }
  }

  for (let it = 0; it < iterations; it++) {
    for (let k = 0; k < contacts.length; k++) {
      const c = contacts[k];
      const invMassSum = invMassSumCache[k];
      if (invMassSum === 0) continue;
      const { a, b, normal } = c;

      // --- Normal constraint (restitution = 0) ---
      const rvx = b.velocity.x - a.velocity.x;
      const rvy = b.velocity.y - a.velocity.y;
      const vn = rvx * normal.x + rvy * normal.y;

      const target = -vn / invMassSum;
      const newImpulse = Math.max(c.normalImpulse + target, 0);
      const dImpulse = newImpulse - c.normalImpulse;
      c.normalImpulse = newImpulse;

      if (dImpulse !== 0) {
        applyPair(a, b, normal.x, normal.y, dImpulse);
      }

      // --- Friction (Coulomb cone against accumulated normal impulse) ---
      const tx = -normal.y;
      const ty = normal.x;
      const rv2x = b.velocity.x - a.velocity.x;
      const rv2y = b.velocity.y - a.velocity.y;
      const vt = rv2x * tx + rv2y * ty;

      const maxFriction = friction * c.normalImpulse;
      let jt = -vt / invMassSum;
      jt = Math.max(-maxFriction, Math.min(maxFriction, jt));

      if (jt !== 0) {
        applyPair(a, b, tx, ty, jt);
      }
    }
  }

  // Store accumulated impulses for the next step's warm start.
  impulseCache.clear();
  for (const c of contacts) {
    impulseCache.set(contactKey(c), c.normalImpulse);
  }
}

/**
 * Baumgarte-style positional correction: push penetrating bodies apart by
 * `percent` of the penetration beyond `slop`, split by inverse mass.
 */
export function positionalCorrection(
  contacts: readonly Contact[],
  percent: number,
  slop: number,
): void {
  for (const c of contacts) {
    const invMassSum = c.a.inverseMass + c.b.inverseMass;
    if (invMassSum === 0) continue;
    const magnitude =
      (Math.max(c.penetration - slop, 0) * percent) / invMassSum;
    const cx = magnitude * c.normal.x;
    const cy = magnitude * c.normal.y;
    c.a.position.x -= cx * c.a.inverseMass;
    c.a.position.y -= cy * c.a.inverseMass;
    c.b.position.x += cx * c.b.inverseMass;
    c.b.position.y += cy * c.b.inverseMass;
  }
}

