/**
 * world.ts — simulation container: gravity, fixed-step integration,
 * contact solving and positional correction.
 */

import { Body, type Vec2 } from "./body";
import {
  findContacts,
  positionalCorrection,
  resolveVelocities,
} from "./solver";

export interface WorldOptions {
  gravity?: Vec2;
  /** Solver iterations per step. */
  iterations?: number;
  /** Baumgarte correction percentage (0..1). */
  baumgartePercent?: number;
  /** Allowed penetration before correction kicks in. */
  slop?: number;
}

export class World {
  readonly gravity: Vec2;
  readonly iterations: number;
  readonly baumgartePercent: number;
  readonly slop: number;
  readonly bodies: Body[] = [];

  /**
   * Persistent cache of accumulated contact impulses keyed by body pair.
   * Used to warm-start the solver each step so resting stacks converge.
   */
  private readonly impulseCache = new Map<string, number>();

  constructor(options: WorldOptions = {}) {
    this.gravity = options.gravity ?? { x: 0, y: -9.8 };
    this.iterations = options.iterations ?? 8;
    this.baumgartePercent = options.baumgartePercent ?? 0.8;
    this.slop = options.slop ?? 0.01;
  }

  addBody(body: Body): Body {
    this.bodies.push(body);
    return body;
  }

  /** Advance the simulation by one fixed time step. */
  step(dt: number): void {
    const { bodies } = this;

    // 1. Integrate forces (gravity) into velocities.
    for (const body of bodies) {
      if (body.inverseMass === 0) continue;
      body.velocity.x += this.gravity.x * dt;
      body.velocity.y += this.gravity.y * dt;
    }

    // 2. Detect contacts (warm-started with last step's impulses).
    const contacts = findContacts(bodies, this.impulseCache);

    // 3. Solve velocity constraints (sequential impulses).
    resolveVelocities(contacts, this.iterations, this.impulseCache);

    // 4. Integrate positions.
    for (const body of bodies) {
      if (body.inverseMass === 0) continue;
      body.position.x += body.velocity.x * dt;
      body.position.y += body.velocity.y * dt;
    }

    // 5. Positional correction (Baumgarte-style projection).
    positionalCorrection(contacts, this.baumgartePercent, this.slop);
  }

  /** Run `ticks` steps of size dt. */
  run(ticks: number, dt: number): void {
    for (let i = 0; i < ticks; i++) this.step(dt);
  }

  /** Maximum speed over all dynamic bodies. */
  maxSpeed(): number {
    let max = 0;
    for (const body of this.bodies) {
      if (body.inverseMass === 0) continue;
      max = Math.max(max, body.speed);
    }
    return max;
  }
}

