import { it } from "vitest";
import { Body } from "./src/body";
import { World } from "./src/world";
const DT = 1/60;
it("report", () => {
  // single drop
  const w1 = new World();
  w1.addBody(new Body({ position:{x:0,y:-5}, halfExtent:{x:100,y:5}, isStatic:true }));
  const box = w1.addBody(new Body({ position:{x:0,y:5.5}, halfExtent:{x:0.5,y:0.5}, mass:1 }));
  let t=0; do { w1.step(DT); t++; } while (w1.maxSpeed()>=0.01 && t<600);
  console.log(`drop: ticks=${t} speed=${box.speed.toExponential(2)} penetration=${(0-(box.position.y-0.5)).toFixed(6)}`);
  // stack
  const w2 = new World();
  w2.addBody(new Body({ position:{x:0,y:-5}, halfExtent:{x:100,y:5}, isStatic:true }));
  const boxes = [0,1,2].map(i => w2.addBody(new Body({ position:{x:0,y:i+2.5}, halfExtent:{x:0.5,y:0.5}, mass:1 })));
  let t2=0; do { w2.step(DT); t2++; } while (w2.maxSpeed()>=0.01 && t2<600);
